-- 14.10.2026: ad_daily_real joins orders on utm_content = ad_id (URL parameters by ids) or the old name form; medium match case-insensitive.
DROP VIEW IF EXISTS ad_daily_real;
CREATE VIEW ad_daily_real AS SELECT d.*, COALESCE(o.n, 0) AS real_orders, COALESCE(o.rev, 0) AS real_revenue, CASE WHEN EXISTS (SELECT 1 FROM ad_events e WHERE e.project='barpi' AND e.status <> 'cancelled' AND e.starts_at < d.day || 'T21:00:00Z' AND e.ends_at > date(d.day, '-1 day') || 'T21:00:00Z') THEN 'promo' ELSE 'normal' END AS day_type FROM ad_daily d LEFT JOIN (SELECT day_kyiv, utm_content, count(*) AS n, sum(value) AS rev FROM ad_orders WHERE COALESCE(paid_status,'') <> 'cancelled' AND (lower(substr(utm_medium,1,9))='facebook_' OR lower(substr(utm_medium,1,10))='instagram_' OR lower(substr(utm_medium,1,10))='messenger_' OR lower(substr(utm_medium,1,17))='audience_network_' OR lower(substr(utm_medium,1,8))='threads_' OR utm_medium='facebook_ads') GROUP BY day_kyiv, utm_content) o ON o.day_kyiv = d.day AND (o.utm_content = d.ad_id OR o.utm_content = d.adset_name || '_' || d.ad_name);
